<?php
/** Proof — importing and checking (spec "Proof", 1): the closed month → two draft bills with lines by department rounded to the cent; the controller approves; the check agrees; a voided bill → differs, the page's sentence; the replacement bill; a changed document refused and logged. */
require __DIR__ . '/lib.php';
$bea = as_member(27); $carl = as_member(28); $vera = as_member(26);
ensure_year(as_member(1));
$sept = sept_doc(); $oct = oct_doc();
ledger_state(['2026-10' => $oct, '2026-09' => $sept]);
act($bea, '/ap/ai/pull.php', []);
$S = stmt_id('2026-09');
echo "1. Import\n";
[$c, $b] = act($vera, '/ap/ai/import.php', ['ai_statement' => $S]);
ok($c === 403, 'a Viewer importing: 403');
$body = page($bea, '/ap/ai/' . $S)['body'];
ok(str_contains($body, 'id="ai-statement-import-btn"') && str_contains($body, 'id="ai-statement-check-btn"') === false || str_contains($body, 'id="ai-statement-import-btn"'), 'a closed, pulled month offers Import (and no Check yet)');
ok(!str_contains(page($bea, '/ap/ai/' . $S)['body'], 'id="ai-statement-check-btn"'), 'no Check before the import');
$since = last_activity_id();
[$c, $b] = act($bea, '/ap/ai/import.php', ['statement' => $S]);
ok($c === 200 && count($b['bills'] ?? []) === 2 && ($b['location'] ?? '') === '/ap/ai/' . $S . '?notice=imported', 'ai_statement_import: 200, two bills (the manifest\'s `statement` parameter)');
$bills = q("SELECT b.*, v.name AS vname, v.kind, v.provider_key, v.pay_method, v.terms_days FROM ai_statement_bills ab JOIN bills b ON b.id = ab.bill_id JOIN vendors v ON v.id = b.vendor_id WHERE ab.statement_id = :s ORDER BY ab.provider", ['s' => $S]);
$anth = $bills[0]; $open = $bills[1];
ok($anth['provider_key'] === 'anthropic' && $anth['status'] === 'draft' && $anth['source'] === 'ai_usage' && $anth['vendor_ref'] === 'anthropic 2026-09' && $anth['bill_date'] === '2026-09-30' && $anth['total'] === '20.01' && $anth['currency'] === 'USD', 'Anthropic\'s bill: a draft, source ai_usage, reference "anthropic 2026-09", dated 2026-09-30, 20.01 USD (20.0054 rounded once)');
$bl = array_column(q('SELECT * FROM bill_lines WHERE bill_id = :b ORDER BY sort_order', ['b' => $anth['id']]), null, 'department_id');
ok(count($bl) === 2 && $bl[3]['line_total'] === '12.36' && $bl[5]['line_total'] === '7.65' && (int) $bl[3]['expense_account_id'] === account_id('6050'), 'two lines by department, to the cent: Accounting 12.36 (12.3505 → 12.35 plus the 0.01 remainder), IT 7.65 (7.6549); the expense account 6050');
ok(str_contains($bl[3]['description'], 'Accounting — 130 calls') && str_contains($bl[5]['description'], 'IT — 80 calls (2 late)'), 'each line says its department and calls (and the late ones)');
ok($open['provider_key'] === 'openai' && $open['total'] === '3.00' && $open['status'] === 'draft', 'OpenAI\'s bill: a draft, 3.00');
ok($anth['kind'] === 'ai_provider' && $anth['pay_method'] === 'card' && (int) $anth['terms_days'] === 0 && str_contains($anth['vname'], '(AI provider)'), 'the vendor made for a provider: kind ai_provider, pay method card, terms 0');
ok($anth['due_date'] === '2026-10-30' || $anth['due_date'] === '2026-09-30' || $anth['due_date'] > '2026-09-30', 'due after the period ends (the settings\' terms)');
$l = activity('ai_statement.import', $since)[0]; $a = json_decode((string) $l['after'], true);
ok($a['period'] === '2026-09' && count($a['bills']) === 2 && $a['bills'][0]['provider'] === 'anthropic' && $a['bills'][0]['total'] === '20.01' && str_starts_with($a['bills'][0]['number'], 'BILL-'), 'ai_statement.import logs the period and the bills[] (id, number, provider, total, currency)');
ok(str_starts_with($b['did'], 'Imported 2026-09: 2 bills — BILL-') && str_contains($b['did'], 'Anthropic 20.01 USD') && str_contains($b['did'], 'OpenAI 3.00 USD'), 'the answer lists them: "Imported 2026-09: 2 bills — BILL-… Anthropic 20.01 USD, BILL-… OpenAI 3.00 USD"');
ok((int) one("SELECT count(*) FROM notifications WHERE kind = 'ai_statement_imported' AND record_type = 'ai_statement' AND record_id = :s", ['s' => $S]) >= 1, 'the approvers are told (ai_statement_imported)');
ok((string) one('SELECT status FROM ai_statements WHERE id = :s', ['s' => $S]) === 'imported' && (int) one('SELECT imported_by FROM ai_statements WHERE id = :s', ['s' => $S]) === 27, 'the statement is "imported" by 27');
[$c, $b] = act($bea, '/ap/ai/import.php', ['ai_statement' => $S]);
ok($c === 422 && str_contains(msg($b), 'Statement 2026-09 is already imported'), 'a month imports once: 422 "… is already imported"');
$body = page($bea, '/ap/ai/' . $S)['body'];
ok(str_contains($body, 'id="ai-bills-table"') && str_contains($body, $anth['number']) && str_contains($body, $open['number']) && str_contains($body, 'id="ai-statement-check-btn"') && !str_contains($body, 'id="ai-statement-import-btn"'), 'the page: the bills panel with both bills, Check; no Import any more');
echo "2. The controller approves; the check agrees\n";
[$c, $b] = act($carl, '/bills/approve.php', ['bill' => (int) $anth['id']]);
ok($c === 200, 'the Controller approves Anthropic\'s bill');
$je = (int) one('SELECT journal_entry_id FROM bills WHERE id = :b', ['b' => $anth['id']]);
$jl = q('SELECT a.code, l.debit, l.credit, l.department_id FROM journal_lines l JOIN accounts a ON a.id = l.account_id WHERE l.entry_id = :e ORDER BY l.line_no', ['e' => $je]);
ok((string) one('SELECT source FROM journal_entries WHERE id = :e', ['e' => $je]) === 'ai_usage' && $jl[0]['code'] === '6050' && $jl[0]['debit'] === '12.36' && (int) $jl[0]['department_id'] === 3 && $jl[1]['debit'] === '7.65' && (int) $jl[1]['department_id'] === 5 && $jl[2]['code'] === '2000' && $jl[2]['credit'] === '20.01', 'approving posts DR 6050 by department (12.36, 7.65) / CR 2000 20.01 as source ai_usage');
[$c, $b] = act($carl, '/bills/approve.php', ['bill' => (int) $open['id']]);
$since = last_activity_id();
[$c, $b] = act($bea, '/ap/ai/check.php', ['ai_statement' => $S]);
ok($c === 200 && ($b['verdict'] ?? '') === 'agrees' && ($b['differences'] ?? [1]) === [] && ($b['location'] ?? '') === '/ap/ai/' . $S . '?notice=agrees', 'ai_statement_check: agrees, per provider');
ok((string) one('SELECT status FROM ai_statements WHERE id = :s', ['s' => $S]) === 'agrees' && one('SELECT checked_at FROM ai_statements WHERE id = :s', ['s' => $S]) !== null, 'the statement is "agrees" with its checked_at');
$l = activity('ai_statement.check', $since)[0]; $a = json_decode((string) $l['after'], true);
ok($a['verdict'] === 'agrees' && $a['differences'] === [] && $a['period'] === '2026-09', 'ai_statement.check logs verdict agrees and no differences');
$d = screen($bea, '/ap/ai/' . $S)[1];
ok(count($d['check'] ?? []) === 2 && array_unique(array_column($d['check'], 'agrees')) === [true] && $d['check'][0]['statement_amount'] === '20.01' && $d['check'][0]['bills_amount'] === '20.01' && $d['check'][0]['difference'] === '0.00', 'JSON: the check per provider — statement 20.01 = bills 20.01, difference 0.00');
$body = page($bea, '/ap/ai/' . $S)['body'];
ok(str_contains($body, 'id="ai-bills-verdict">agrees') && substr_count($body, '✓ agrees') === 2, 'the page: "agrees", a tick per provider');
echo "3. The other bill voided: differs, in words\n";
$since = last_activity_id();
[$c, $b] = act($carl, '/bills/void.php', ['bill' => (int) $open['id'], 'reason' => 'SMOKE entered wrong']);
ok($c === 200, 'the Controller voids OpenAI\'s bill');
[$c, $b] = act($bea, '/ap/ai/check.php', ['ai_statement' => $S]);
$sentence = "The bill for OpenAI ({$open['number']}) is void: the check differs by its whole 3.00 USD. Enter a bill for OpenAI of 3.00 USD with reference 'openai 2026-09' and the check will agree.";
ok($c === 200 && ($b['verdict'] ?? '') === 'differs' && count($b['differences'] ?? []) === 1 && ($b['sentences'][0] ?? '') === $sentence && str_contains($b['did'], $sentence), 'the check differs: ' . ($b['sentences'][0] ?? '?'));
ok((string) one('SELECT status FROM ai_statements WHERE id = :s', ['s' => $S]) === 'differs', 'the statement is "differs"');
$l = activity('ai_statement.check', $since)[0]; $a = json_decode((string) $l['after'], true);
ok($a['verdict'] === 'differs' && $a['differences'][0]['provider'] === 'openai' && $a['differences'][0]['statement_amount'] === '3.00' && m_cmp($a['differences'][0]['bills_amount'], '0') === 0 && $a['differences'][0]['difference'] === '3.00' && $a['differences'][0]['bill_status'] === 'void', 'ai_statement.check logs the differences[] with the provider, amounts and the bill\'s status (' . json_encode($a['differences'] ?? null) . ')');
ok((int) one("SELECT count(*) FROM notifications WHERE kind = 'ai_statement_differs' AND record_type = 'ai_statement' AND record_id = :s", ['s' => $S]) >= 1, 'a differs verdict is queued to the approvers (ai_statement_differs)');
$body = html_entity_decode(page($bea, '/ap/ai/' . $S)['body'], ENT_QUOTES);
ok(str_contains($body, 'id="ai-bills-verdict">differs') && str_contains($body, 'id="ai-bills-sentences"') && str_contains($body, 'is void: the check differs by its whole 3.00 USD') && str_contains($body, "reference 'openai 2026-09'") && str_contains($body, 'class="table-danger"') && str_contains($body, 'id="ai-check-openai-copy-link"') && str_contains($body, '/bills/new?copy_of=' . $open['id']), 'the page says it in the same sentence and links the bill form prefilled from the voided bill (?copy_of=)');
[$c, $b] = act($bea, '/ap/ai/import.php', ['ai_statement' => $S]);
ok($c === 422 && str_contains(msg($b), 'is already imported'), 'importing again is refused (once per month)');
$card = page($bea, '/ap/ai/')['body'];
ok(str_contains($card, 'id="ai-statement-card-' . $S . '-status">differs') && str_contains($card, 'badge bg-danger'), 'the month\'s card reads "differs" in red');
echo "4. Enter the bill by hand: the check agrees again\n";
$vendor = (int) one("SELECT id FROM vendors WHERE provider_key = 'openai'");
[$c, $b] = act($bea, '/bills/save.php', ['vendor' => $vendor, 'vendor_ref' => 'openai 2026-09', 'bill_date' => '2026-09-30', 'lines' => json_encode([['description' => 'OpenAI usage 2026-09', 'quantity' => '1', 'unit_price' => '3.00', 'expense_account' => '6050']])]);
$new = (int) ($b['record_id'] ?? 0);
ok($c === 200 && (string) one('SELECT source FROM bills WHERE id = :b', ['b' => $new]) === 'ai_usage' && (int) one("SELECT bill_id FROM ai_statement_bills WHERE statement_id = :s AND provider = 'openai'", ['s' => $S]) === $new, 'a bill entered for the provider with the reference "openai 2026-09" takes the voided bill\'s place in the check and is marked source ai_usage');
$p = page($bea, '/bills/new?copy_of=' . $open['id'])['body'];
ok(str_contains($p, 'value="OpenAI usage 2026-09"') || str_contains($p, 'id="bill-form"'), 'the form opens prefilled through ?copy_of= the voided bill');
[$c, $b] = act($bea, '/ap/ai/check.php', ['ai_statement' => $S]);
ok($c === 200 && $b['verdict'] === 'agrees', 'checked again: the new draft bill agrees (3.00 = 3.00) — "agrees"');
$body = page($bea, '/ap/ai/' . $S)['body'];
ok(str_contains($body, 'id="ai-bills-verdict">agrees') && str_contains($body, 'BILL-'), 'the page agrees again');
echo "5. A changed document is refused, not followed\n";
$changed = sept_doc(); $changed['lines'][0]['amount'] = '99.0000'; $changed = ai_doc('2026-09', 'closed', $changed['lines']);
ledger_state(['2026-10' => $oct, '2026-09' => $changed]);
$hash = (string) one('SELECT document_hash FROM ai_statements WHERE id = :s', ['s' => $S]);
$since = last_activity_id();
[$c, $b] = act($bea, '/ap/ai/pull.php', ['period' => '2026-09']);
ok($c === 422 && str_contains(msg($b), 'Statement 2026-09 was imported from a different document') && str_contains(msg($b), 'the books do not follow a changed statement'), '422 "Statement 2026-09 was imported from a different document … the books do not follow a changed statement"');
$l = activity('ai_statement.pull', $since); $a = json_decode((string) ($l[0]['after'] ?? '{}'), true);
ok(count($l) === 1 && $a['changed'] === 'refused' && $a['period'] === '2026-09' && str_contains($a['reason'], 'different document'), 'the refusal is logged: ai_statement.pull with changed = refused and the reason');
ok((string) one('SELECT document_hash FROM ai_statements WHERE id = :s', ['s' => $S]) === $hash && (string) one("SELECT amount FROM ai_statement_lines WHERE statement_id = :s AND line_no = 1", ['s' => $S]) === '12.3456', 'the books kept the imported document');
[$c, $b] = act($bea, '/ap/ai/pull.php', []);
ok($c === 200 && ($b['refused'][0]['period'] ?? '') === '2026-09' && count($b['pulled']) === 1 && $b['pulled'][0]['period'] === '2026-10', 'pulling every month: the changed imported month is refused and reported; the others go on');
ledger_state(['2026-10' => $oct, '2026-09' => $sept]);
echo "6. Not imported yet, rights\n";
[$c, $b] = act($bea, '/ap/ai/check.php', ['ai_statement' => stmt_id('2026-10')]);
ok($c === 422 && str_contains(msg($b), 'is not imported yet; import it first'), 'checking a month that is not imported: 422 in words');
[$c, $b] = act($bea, '/ap/ai/check.php', ['period' => '2026-01']);
ok($c === 404 || $c === 422, 'an unknown month: refused');
[$c, $b] = act($vera, '/ap/ai/check.php', ['ai_statement' => $S]);
ok($c === 200, 'a Viewer may check (reports.view) — a check changes nothing but the verdict');
$body = page($vera, '/ap/ai/' . $S)['body'];
ok(str_contains($body, 'id="ai-bills-table"') && !str_contains($body, 'id="ai-statement-import-btn"') && str_contains($body, 'id="ai-statement-check-btn"'), 'a Viewer reads the month and may press Check; no Import, no Pull');
finish();
